import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.awt.datatransfer.StringSelection;
import java.nio.file.*;
import java.io.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.zip.CRC32;

/** Local desktop front end. All filesystem operations run outside the EDT. */
public final class Desktop {
    static final Color BG=new Color(20,25,34), FG=new Color(231,237,245), ACCENT=new Color(85,160,221);
    static JFrame frame;
    static JTextArea output(int rows){JTextArea a=new JTextArea(rows,50);a.setEditable(false);a.setLineWrap(true);a.setWrapStyleWord(true);a.setFont(new Font(Font.MONOSPACED,Font.PLAIN,14));return a;}
    static JPanel panel(){JPanel p=new JPanel(new BorderLayout(12,12));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));return p;}
    static JPanel row(Component... items){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,8,5));for(Component c:items)p.add(c);return p;}
    static JButton button(String name,Runnable action){JButton b=new JButton(name);b.addActionListener(e->action.run());return b;}
    static void error(Throwable e){JOptionPane.showMessageDialog(frame,e.getMessage()==null?e.toString():e.getMessage(),"Operation failed",JOptionPane.ERROR_MESSAGE);}
    static Path choose(boolean directory,boolean save){JFileChooser c=new JFileChooser();if(directory)c.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);int r=save?c.showSaveDialog(frame):c.showOpenDialog(frame);return r==JFileChooser.APPROVE_OPTION?c.getSelectedFile().toPath():null;}
    static <T> void task(JButton b,Callable<T> job,java.util.function.Consumer<T> result){b.setEnabled(false);new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return job.call();}protected void done(){try{result.accept(get());}catch(Exception e){error(e.getCause()==null?e:e.getCause());}finally{b.setEnabled(true);}}}.execute();}
    static JPanel password(){JPanel p=panel(), top=new JPanel(new GridLayout(0,1));JSpinner n=new JSpinner(new SpinnerNumberModel(32,1,4096,1));JComboBox<String> mode=new JComboBox<>(new String[]{"ascii","mixed","random","greek","cyrillic","hebrew","arabic","custom"});JTextField custom=new JTextField(18);JTextArea secret=output(5);JLabel stats=new JLabel("Ready — passwords are never saved by this program.");
        JButton gen=button("Generate",()->{try{int[] pool=PasswordGeneration.pool((String)mode.getSelectedItem(),custom.getText());int length=(Integer)n.getValue();secret.setText(PasswordGeneration.generate(length,pool));stats.setText(String.format(Locale.ROOT,"%d code points | %d symbols | %.1f bits theoretical entropy",length,pool.length,length*Math.log(pool.length)/Math.log(2)));}catch(Exception ex){error(ex);}});
        top.add(row(new JLabel("Length"),n,new JLabel("Alphabet"),mode));top.add(row(new JLabel("Custom symbols"),custom));top.add(row(gen,button("Copy",()->{if(!secret.getText().isEmpty())try{Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(secret.getText()),null);stats.setText("Copied — clipboard history may retain the password.");}catch(Exception e){error(e);}}),button("Clear",()->{secret.setText("");stats.setText("Cleared from view; clipboard is not cleared.");})));top.add(stats);p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(secret));p.add(new JLabel("ASCII is most compatible. Unicode may be rejected or normalized by other services."),BorderLayout.SOUTH);return p;}
    static JPanel carving(){JPanel p=panel(),top=new JPanel(new GridLayout(0,1));JTextField src=new JTextField(38),dst=new JTextField(38);JTextArea log=output(12);JButton run=new JButton("Recover files");top.add(row(new JLabel("Disk image"),src,button("Browse",()->{Path x=choose(false,false);if(x!=null)src.setText(x.toString());})));top.add(row(new JLabel("Output folder"),dst,button("Browse",()->{Path x=choose(true,false);if(x!=null)dst.setText(x.toString());})));top.add(row(run));run.addActionListener(e->{try{Path a=Path.of(src.getText()),b=Path.of(dst.getText());if(src.getText().isBlank()||dst.getText().isBlank())throw new IOException("Select both paths");log.setText("Scanning read-only image. Large files can take time.\n");task(run,()->FileCarving.recover(a,b),count->log.append("Recovered candidates: "+count+"\nOutput: "+b.toAbsolutePath()+"\nRead the TSV report for validation levels and SHA-256.\nLimits: "+FileCarving.MAX/1048576+" MiB per candidate; 1000 results; 10000 candidate attempts. Results may be incomplete.\n"));}catch(Exception ex){error(ex);}});p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(log));return p;}
    static JPanel metadata(){JPanel p=panel(),top=new JPanel(new GridLayout(0,1));JTextField src=new JTextField(38);JLabel score=new JLabel("Open an image or Office document.");DefaultTableModel model=new DefaultTableModel(new Object[]{"Field","Original value","Risk","Action","Replacement"},0){public boolean isCellEditable(int r,int c){return c>=3;}};JTable table=new JTable(model);table.getColumnModel().getColumn(3).setCellEditor(new DefaultCellEditor(new JComboBox<>(new String[]{"Keep","Replace","Remove"})));JButton inspect=new JButton("Inspect"),export=new JButton("Export edited copy"),strip=new JButton("Strip common JPEG/PNG metadata");export.setEnabled(false);final Path[] loaded={null};
        top.add(row(new JLabel("Source"),src,button("Browse",()->{Path x=choose(false,false);if(x!=null)src.setText(x.toString());})));top.add(row(inspect,export,strip));top.add(score);inspect.addActionListener(e->{export.setEnabled(false);loaded[0]=null;model.setRowCount(0);try{Path x=Path.of(src.getText());if(src.getText().isBlank()||!Files.isRegularFile(x))throw new IOException("Select a regular file");task(inspect,()->MetadataScore.inspect(x),fields->{for(var f:fields)model.addRow(new Object[]{f.key(),f.value(),f.risk(),"Keep",""});score.setText("Exposure: "+MetadataScore.score(fields)+"/100 (heuristic). Edit Action and Replacement columns.");loaded[0]=x;export.setEnabled(MetadataScore.IMAGE.contains(MetadataScore.ext(x))||MetadataScore.OFFICE.contains(MetadataScore.ext(x)));});}catch(Exception ex){error(ex);}});
        export.addActionListener(e->{if(table.isEditing())table.getCellEditor().stopCellEditing();Map<String,String> changes=new LinkedHashMap<>();for(int i=0;i<model.getRowCount();i++){String action=(String)model.getValueAt(i,3);if(!action.equals("Keep")){String v=action.equals("Remove")?"":String.valueOf(model.getValueAt(i,4));if(action.equals("Replace")&&v.isEmpty()){error(new IOException("Replacement is empty; select Remove explicitly"));return;}String key=(String)model.getValueAt(i,0);if(changes.putIfAbsent(key,v)!=null){error(new IOException("Duplicate tag selected: "+key));return;}}}if(changes.isEmpty()){error(new IOException("No changes selected"));return;}Path dest=choose(false,true),source=loaded[0];if(dest!=null)task(export,()->{MetadataScore.export(source,dest,changes);return MetadataScore.inspect(dest);},fields->{model.setRowCount(0);for(var f:fields)model.addRow(new Object[]{f.key(),f.value(),f.risk(),"Keep",""});loaded[0]=dest;src.setText(dest.toString());score.setText("Export re-inspected: "+MetadataScore.score(fields)+"/100. Verify each selected field; other metadata may remain.");});});
        strip.addActionListener(e->{try{Path x=Path.of(src.getText());if(src.getText().isBlank()||!Files.isRegularFile(x))throw new IOException("Select a JPEG or PNG");Path dest=choose(false,true);if(dest!=null)task(strip,()->stripImage(x,dest),count->JOptionPane.showMessageDialog(frame,"Removed "+count+" common metadata segments/chunks. Original unchanged. JPEG orientation may change. Not an anonymity guarantee."));}catch(Exception ex){error(ex);}});
        p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(table));p.add(new JLabel("Office core fields: built in. Image inspection/editing: ExifTool. Basic JPEG/PNG stripping: built in."),BorderLayout.SOUTH);return p;}
    /** Copy-only lossless stripping of common metadata. No decompression or pixel re-encoding. */
    static int stripImage(Path src,Path dst)throws IOException{String ext=MetadataScore.ext(src);if(!Set.of("jpeg","jpg","png").contains(ext)||!ext.equals(MetadataScore.ext(dst))||Files.exists(dst))throw new IOException("Choose a new JPEG/PNG path with the same extension");Path temp=Files.createTempFile(dst.toAbsolutePath().getParent(),"strip-",".tmp");int removed=0;try{try(DataInputStream in=new DataInputStream(new BufferedInputStream(Files.newInputStream(src)));DataOutputStream out=new DataOutputStream(new BufferedOutputStream(Files.newOutputStream(temp)))){if(ext.equals("png")){byte[] sig=in.readNBytes(8);if(!Arrays.equals(sig,java.util.HexFormat.of().parseHex("89504e470d0a1a0a")))throw new IOException("Invalid PNG signature");out.write(sig);boolean first=true;while(true){long len=Integer.toUnsignedLong(in.readInt());byte[] type=in.readNBytes(4);if(type.length!=4||len>64L*1024*1024)throw new IOException("Invalid or oversized PNG chunk");String name=new String(type,java.nio.charset.StandardCharsets.US_ASCII);if(first&&(!name.equals("IHDR")||len!=13))throw new IOException("Missing IHDR");first=false;boolean drop=Set.of("tEXt","zTXt","iTXt","eXIf","tIME").contains(name);if(drop)removed++;else{out.writeInt((int)len);out.write(type);}CRC32 crc=new CRC32();crc.update(type);byte[] b=new byte[65536];for(long left=len;left>0;){int n=(int)Math.min(b.length,left);in.readFully(b,0,n);crc.update(b,0,n);if(!drop)out.write(b,0,n);left-=n;}int expected=in.readInt();if(crc.getValue()!=Integer.toUnsignedLong(expected))throw new IOException("PNG CRC failure: "+name);if(!drop)out.writeInt(expected);if(name.equals("IEND")){if(len!=0)throw new IOException("Invalid IEND");break;}}}else{if(in.readUnsignedShort()!=0xffd8)throw new IOException("Invalid JPEG signature");out.writeShort(0xffd8);while(true){if(in.readUnsignedByte()!=255)throw new IOException("Invalid JPEG marker");int marker;do{marker=in.readUnsignedByte();}while(marker==255);if(marker==0xd9){out.writeShort(0xffd9);break;}if(marker==0||marker==0xd8||marker>=0xd0&&marker<=0xd7)throw new IOException("Unexpected JPEG marker");int len=in.readUnsignedShort();if(len<2)throw new IOException("Invalid JPEG segment length");byte[] data=in.readNBytes(len-2);if(data.length!=len-2)throw new EOFException("Truncated JPEG segment");boolean drop=marker==0xe1||marker==0xed||marker==0xfe;if(drop)removed++;else{out.writeByte(255);out.writeByte(marker);out.writeShort(len);out.write(data);}if(marker==0xda){int a,previous=-1;boolean ended=false;while((a=in.read())!=-1){out.write(a);if(previous==255&&a==0xd9){ended=true;break;}previous=a;}if(!ended)throw new IOException("Missing JPEG EOI");break;}}}}Files.move(temp,dst);return removed;}finally{Files.deleteIfExists(temp);}}
    public static void main(String[] args){if(args.length>0&&args[0].equals("--self-test")){try{Path d=Files.createTempDirectory("strip-test");var im=new java.awt.image.BufferedImage(8,8,java.awt.image.BufferedImage.TYPE_INT_RGB);for(String ext:List.of("png","jpg")){Path a=d.resolve("a."+ext),b=d.resolve("b."+ext);javax.imageio.ImageIO.write(im,ext,a.toFile());stripImage(a,b);if(javax.imageio.ImageIO.read(b.toFile()).getWidth()!=8)throw new AssertionError();}System.out.println("Desktop image copy tests passed");return;}catch(Exception e){throw new RuntimeException(e);}}SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel("javax.swing.plaf.nimbus.NimbusLookAndFeel");UIManager.put("control",BG);UIManager.put("nimbusBase",new Color(35,52,70));UIManager.put("nimbusLightBackground",new Color(29,36,47));UIManager.put("text",FG);UIManager.put("nimbusSelectedText",Color.WHITE);UIManager.put("nimbusSelectionBackground",new Color(45,88,128));UIManager.put("nimbusFocus",ACCENT);UIManager.put("defaultFont",new Font("SansSerif",Font.PLAIN,14));}catch(Exception ignored){}frame=new JFrame("Java Applied Systems | Local Tools");frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Password Generation",password());tabs.addTab("File Carving",carving());tabs.addTab("Metadata Score",metadata());if(args.length>0)try{tabs.setSelectedIndex(Integer.parseInt(args[0]));}catch(Exception ignored){}frame.setContentPane(tabs);frame.setSize(960,570);frame.setMinimumSize(new Dimension(820,490));frame.setLocationRelativeTo(null);frame.setVisible(true);});}
}
